import {cornerSettings,KERB_MODES,turnBoardSettings} from './corner-settings.js?v=20261008-structure-design';
import {buildGeometry} from './engine.js?v=20261008-structure-design';
const $=s=>document.querySelector(s);
const PRESETS={balanced:{rounding:1,entryStrength:1,exitStrength:1},late:{rounding:.85,entryStrength:.6,exitStrength:1.4},early:{rounding:.85,entryStrength:1.4,exitStrength:.6},hairpin:{rounding:.35,entryStrength:.65,exitStrength:.65},sweeper:{rounding:1,entryStrength:1.5,exitStrength:1.5}};
export function mountCorners(api){
  const panel=document.createElement('section');panel.className='panel-section corner-panel';
  panel.innerHTML=`<div class="section-heading"><span class="section-num">TURN</span><h2>Corner workshop</h2><span id="corner-number" class="scene-tag"></span></div><p id="corner-empty" class="field-hint">Shift-click road handles to select several, or choose one point below.</p><div class="corner-navigation"><button id="previous-corner" class="outline-button" aria-label="Previous corner point">←</button><select id="corner-select" aria-label="Choose corner control point"></select><button id="next-corner" class="outline-button" aria-label="Next corner point">→</button></div><p id="corner-selection-note" class="field-hint" role="status"></p><div id="corner-controls" hidden><label class="studio-field">Corner name<input id="corner-name" maxlength="40" placeholder="e.g. Sunset hairpin"></label><button id="corner-structure-edit" class="outline-button">Bridge / tunnel at this handle</button><div class="corner-profile" id="corner-profile"></div><div class="corner-metrics" id="corner-metrics"></div><p class="field-hint">Curve presets shape the approach and departure. The orange dot is your control point.</p><div class="corner-presets" role="group" aria-label="Corner curve presets"><button data-corner-preset="balanced">Balanced</button><button data-corner-preset="late">Long exit</button><button data-corner-preset="early">Long entry</button><button data-corner-preset="hairpin">Tight bend</button><button data-corner-preset="sweeper">Sweeper</button></div><div class="corner-shapes" role="group" aria-label="Corner shape"><button data-rounding="0">Sharp</button><button data-rounding=".35">Tight</button><button data-rounding="1">Rounded</button></div><label class="studio-field">Rounding <output id="rounding-value"></output><input id="corner-rounding" type="range" min="0" max="100" step="1"></label><label class="studio-field">Entry reach <output id="entry-value"></output><input id="corner-entry" type="range" min="0" max="160" step="5"></label><label class="studio-field">Exit reach <output id="exit-value"></output><input id="corner-exit" type="range" min="0" max="160" step="5"></label><p class="field-hint">100% keeps the original curve. Increase reach for a wider sweep; reduce it for a tighter approach. Neighboring sections also change.</p><label class="studio-field">Tangent angle <output id="tangent-value"></output><input id="corner-tangent" type="range" min="-60" max="60" step="1"></label><p class="field-hint">Rotate the direction through this handle. Positive turns clockwise; negative turns counterclockwise. Both adjoining curves share the new direction. The dashed orange line shows it in the preview. Works with Smooth corners.</p><button id="mirror-corner-reach" class="outline-button">Swap entry & exit reach</button><div class="studio-fields"><label class="studio-field">Kerbs<select id="corner-kerbs">${Object.entries(KERB_MODES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="studio-field">Kerb width · m<input id="corner-kerb-width" type="number" min=".25" max="2" step=".05"></label><label class="studio-field">Banking · degrees<input id="corner-banking" type="number" min="-15" max="15" step=".5"></label><label class="studio-field">Elevation · m<input id="corner-elevation" type="number" min="-100" max="500" step=".1"></label></div><p class="field-hint">Elevation and banking blend smoothly into neighboring points, including crests, valleys and the circuit seam. Extend the slope over more points for a gentler gradient.</p><div class="corner-copy-actions"><button id="copy-corner" class="outline-button">Copy style</button><button id="paste-corner" class="outline-button" disabled>Paste style</button></div><button id="reset-corner" class="outline-button">Reset curve & banking</button><p id="corner-hint" class="field-hint"></p></div>`;
  $('.point-section').after(panel);let lastPoints='',copied=null,activeTurnKey='',lastBoardKey='';
  const boardWorkshop=document.createElement('div');boardWorkshop.className='corner-board-workshop';
  boardWorkshop.innerHTML='<div class="corner-board-heading"><h3>Corner distance boards</h3><span id="corner-board-count" class="scene-tag"></span></div><label class="toggle-row"><span>Include boards in mod</span><input id="corner-boards-enabled" type="checkbox"><span class="toggle"></span></label><p class="field-hint">Choose 10 m and 5 m independently for each detected turn. Click a turn to locate its road handle. Numbers follow the driving direction from start/finish.</p><div class="corner-copy-actions"><button id="corner-boards-all" class="outline-button">Both on all turns</button><button id="corner-boards-none" class="outline-button">Clear all boards</button></div><div id="corner-board-list" class="corner-board-list"></div><div id="corner-board-options" hidden><label class="studio-field">Board side<select id="corner-board-side"><option value="auto">Auto · find a clear side</option><option value="left">Left of the driver</option><option value="right">Right of the driver</option></select></label><label class="studio-field">Turn-entry adjustment · m<input id="corner-board-entry" type="number" min="-10" max="10" step=".5"></label><p class="field-hint">Negative moves the turn entry earlier; positive moves it later. Board distances are measured 10 m / 5 m before that entry along the road, including hills. A chosen side never silently switches sides.</p><p id="corner-board-status" class="field-hint" role="status"></p><button id="corner-board-reset" class="outline-button">Reset this turn’s boards</button></div><p id="corner-board-empty" class="field-hint"></p>';
  panel.querySelector('.section-heading').after(boardWorkshop);
  const turnKey=turn=>turn.controlIndex+'/'+turn.boardKey;
  const currentBoardTurn=()=>api.getTurnMarkers().turns.find(turn=>turnKey(turn)===activeTurnKey);
  function updateTurn(turn,change){if(!turn)return;api.updateTrack(t=>{const p=t.points[turn.controlIndex];if(!p)return;p.turnBoards={...p.turnBoards,[turn.boardKey]:{...turnBoardSettings(p.turnBoards?.[turn.boardKey]),...change}};});}
  $('#corner-boards-enabled').onchange=()=>api.updateTrack(t=>t.export={...t.export,distanceMarkers:$('#corner-boards-enabled').checked});
  function setAllBoards(enabled){const turns=api.getTurnMarkers().turns;api.updateTrack(t=>{if(enabled)t.export={...t.export,distanceMarkers:true};for(const turn of turns){const p=t.points[turn.controlIndex];p.turnBoards={...p.turnBoards,[turn.boardKey]:{...turn.boards,ten:enabled,five:enabled}};}});}
  $('#corner-boards-all').onclick=()=>setAllBoards(true);$('#corner-boards-none').onclick=()=>setAllBoards(false);
  $('#corner-board-side').onchange=()=>updateTurn(currentBoardTurn(),{side:$('#corner-board-side').value});
  $('#corner-board-entry').onchange=()=>{const value=Number($('#corner-board-entry').value);if(!Number.isFinite(value)||value< -10||value>10){api.toast('Use a turn-entry adjustment between −10 and +10 meters.');lastBoardKey='';refresh();return;}updateTurn(currentBoardTurn(),{entryOffset:value});};
  $('#corner-board-reset').onclick=()=>updateTurn(currentBoardTurn(),turnBoardSettings());
  function refreshBoards(t){
    const plan=api.getTurnMarkers(),turns=plan.turns,enabled=t.export?.distanceMarkers!==false,selected=api.getSelected();
    let active=currentBoardTurn();if(!active||active.controlIndex!==selected){active=turns.find(turn=>turn.controlIndex===selected)||active||turns[0];activeTurnKey=active?turnKey(active):'';}
    const key=JSON.stringify([turns,plan.markers.map(m=>[m.turnNumber,m.distance]),plan.issues,enabled,activeTurnKey]);if(key===lastBoardKey)return;lastBoardKey=key;
    $('#corner-boards-enabled').checked=enabled;$('#corner-board-count').textContent=turns.length?`${plan.selectedTurns}/${turns.length} TURNS`:'';
    $('#corner-boards-all').disabled=$('#corner-boards-none').disabled=!turns.length;$('#corner-board-options').hidden=!active;
    $('#corner-board-empty').textContent=turns.length?'':'Draw a bend to see detected turns here. Gentle direction changes below 12° are ignored.';
    const list=$('#corner-board-list');list.replaceChildren();
    for(const turn of turns){
      const row=document.createElement('div');row.className='corner-board-row';row.classList.toggle('active',turnKey(turn)===activeTurnKey);
      const locate=document.createElement('button');locate.className='corner-board-locate';locate.type='button';locate.setAttribute('aria-pressed',String(turnKey(turn)===activeTurnKey));locate.setAttribute('aria-label',`Locate turn ${turn.number}${turn.name?' · '+turn.name:''}`);
      const title=document.createElement('b'),detail=document.createElement('small');title.textContent=`T${turn.number} · ${turn.name||turn.direction+' turn'}`;detail.textContent=`${Math.round(turn.angle)}° · ${turn.radius.toFixed(1)} m radius · ${Math.round(turn.length)} m bend`;locate.append(title,detail);
      locate.onclick=()=>{activeTurnKey=turnKey(turn);api.selectPoint(turn.controlIndex);api.focusProgress(turn.progress);};row.append(locate);
      const switches=document.createElement('div');switches.className='corner-board-switches';for(const [field,label] of [['ten','10 m'],['five','5 m']]){const item=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=turn.boards[field];input.setAttribute('aria-label',`${label} board for turn ${turn.number}`);input.onchange=()=>{const checked=input.checked;activeTurnKey=turnKey(turn);api.selectPoint(turn.controlIndex);updateTurn(turn,{[field]:checked});};item.append(input,document.createTextNode(label));switches.append(item);}row.append(switches);
      const status=document.createElement('small');status.className='corner-board-row-status';const requested=Number(turn.boards.ten)+Number(turn.boards.five),placed=plan.markers.filter(m=>m.turnNumber===turn.number).length;
      status.textContent=!requested?'No boards':!enabled?'Selected · mod switch off':placed===requested?`${placed} board${placed===1?'':'s'} placed`:`${placed}/${requested} placed · review this turn`;status.classList.toggle('warning',enabled&&placed<requested);row.append(status);list.append(row);
    }
    if(active){$('#corner-board-side').value=active.boards.side;$('#corner-board-entry').value=active.boards.entryOffset;const issues=plan.issues.filter(issue=>issue.turn===active.number);$('#corner-board-status').textContent=`T${active.number} · road handle ${active.controlIndex+1} · entry ${Math.round(active.entryDistanceMeters)} m from ${t.complete!==false?'start/finish':'road start'}. `+(!enabled?'Enable Include boards in mod to export the selected boards.':issues.length?issues.map(issue=>`${issue.distance} m: ${issue.reason}.`).join(' '):'Selections appear in the drawing, 3D preview and next export.');}
  }
  const select=index=>{const t=api.getTrack();if(t.points.length)api.selectPoint((index+t.points.length)%t.points.length);};
  $('#corner-select').onchange=()=>select(Number($('#corner-select').value));$('#previous-corner').onclick=()=>select(Math.max(0,api.getSelected())-1);$('#next-corner').onclick=()=>select(api.getSelected()+1);
  const change=(key,value)=>{const i=api.getSelected();if(i<0)return;api.updateSelectedPoints(p=>p[key]=value);};
  $('#corner-structure-edit').onclick=()=>api.showPanel('.structure-panel');
  $('#corner-name').onchange=()=>change('cornerName',$('#corner-name').value.trim());
  $('#corner-tangent').oninput=()=>{const value=Number($('#corner-tangent').value);$('#tangent-value').textContent=`${value>0?'+':''}${value}°`;const t=api.getTrack(),i=api.getSelected();if(i>=0)drawPreview(t,i,{tangentRotation:value});};
  $('#corner-tangent').onchange=()=>change('tangentRotation',Number($('#corner-tangent').value));
  $('#mirror-corner-reach').onclick=()=>api.updateSelectedPoints(p=>{const settings=cornerSettings(p);p.entryStrength=settings.exitStrength;p.exitStrength=settings.entryStrength;});
  panel.querySelectorAll('[data-rounding]').forEach(b=>b.onclick=()=>change('rounding',Number(b.dataset.rounding)));
  panel.querySelectorAll('[data-corner-preset]').forEach(b=>b.onclick=()=>{const i=api.getSelected();if(i<0)return;api.updateSelectedPoints((p,i,t)=>{t.smooth=true;Object.assign(p,PRESETS[b.dataset.cornerPreset]);});});
  for(const [id,key,out] of [['rounding','rounding','rounding'],['entry','entryStrength','entry'],['exit','exitStrength','exit']]){
    $('#corner-'+id).oninput=()=>{const value=Number($('#corner-'+id).value)/100;$('#'+out+'-value').textContent=`${Math.round(value*100)}%`;const t=api.getTrack(),i=api.getSelected();if(i>=0)drawPreview(t,i,{[key]:value});};
    $('#corner-'+id).onchange=()=>change(key,Number($('#corner-'+id).value)/100);
  }
  $('#corner-kerbs').onchange=()=>change('kerbs',$('#corner-kerbs').value);
  for(const [id,key,min,max] of [['corner-kerb-width','kerbWidth',.25,2],['corner-banking','bank',-15,15],['corner-elevation','elevation',-100,500]])$('#'+id).onchange=()=>{const v=Number($('#'+id).value);if(!Number.isFinite(v)||v<min||v>max){api.toast(`Enter a value between ${min} and ${max}.`);refresh();return;}change(key,v);};
  $('#copy-corner').onclick=()=>{const p=api.getTrack().points[api.getSelected()];if(!p)return;const {cornerName,turnBoards,structure,...style}=cornerSettings(p);copied={...style,bank:p.bank||0};refresh();api.toast('Corner style copied. Choose another point and paste.');};
  $('#paste-corner').onclick=()=>{const i=api.getSelected();if(copied&&i>=0)api.updateSelectedPoints(p=>Object.assign(p,copied));};
  $('#reset-corner').onclick=()=>{const i=api.getSelected();if(i>=0)api.updateSelectedPoints(p=>{const name=p.cornerName,boards=p.turnBoards,structure=p.structure;Object.assign(p,cornerSettings(),{cornerName:name,turnBoards:boards||{},structure,bank:0});});};
  function drawPreview(t,i,override={}){
    const selected=new Set(api.getSelectedPoints()),points=t.points.map((p,j)=>selected.has(j)?{...p,...override}:p),g=buildGeometry(points,t.smooth,t.complete!==false,t),n=points.length,previous=(i+n-1)%n;
    const curve=g.samples.filter((_,j)=>g.segments[j]===previous||g.segments[j]===i),p=points[i];
    if(!curve.length)curve.push(p);
    const minX=Math.min(...curve.map(p=>p.x)),maxX=Math.max(...curve.map(p=>p.x)),minY=Math.min(...curve.map(p=>p.y)),maxY=Math.max(...curve.map(p=>p.y));
    const s=Math.min(230/Math.max(1,maxX-minX),110/Math.max(1,maxY-minY));const xy=p=>[135+(p.x-(minX+maxX)/2)*s,75+(p.y-(minY+maxY)/2)*s];
    const paths=[previous,i].map(segment=>{const list=g.samples.filter((_,j)=>g.segments[j]===segment);if(list.length)list.push(points[(segment+1)%n]);return list.map((p,j)=>`${j?'L':'M'}${xy(p).map(v=>v.toFixed(2)).join(' ')}`).join('');});
    const before=points[t.complete!==false?previous:Math.max(0,i-1)],after=points[t.complete!==false?(i+1)%n:Math.min(n-1,i+1)];
    const center=xy(p),tangentAngle=Math.atan2(after.y-before.y,after.x-before.x)+(Number(p.tangentRotation)||0)*Math.PI/180,tx=Math.cos(tangentAngle)*30,ty=Math.sin(tangentAngle)*30;
    const tangent=t.smooth&&cornerSettings(p).rounding>0?`<path d="M${center[0]-tx} ${center[1]-ty} L${center[0]+tx} ${center[1]+ty}" fill="none" stroke="#dc8553" stroke-width="1.5" stroke-dasharray="3 3"/><circle cx="${center[0]+tx}" cy="${center[1]+ty}" r="2.5" fill="#dc8553"/>`:'';
    $('#corner-profile').innerHTML=`<svg viewBox="0 0 270 150" role="img" aria-label="Actual entry and exit curve around the selected point">${paths.map(d=>`<path d="${d}" fill="none" stroke="#364d44" stroke-width="12" stroke-linejoin="round" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#efe8d3" stroke-width="1.2" stroke-dasharray="4 5"/>`).join('')}${tangent}<circle cx="${xy(p)[0]}" cy="${xy(p)[1]}" r="5" fill="#dc8553" stroke="#fff4df" stroke-width="2"/></svg>`;
    const a=Math.atan2(p.y-before.y,p.x-before.x),b=Math.atan2(after.y-p.y,after.x-p.x),angle=Math.atan2(Math.sin(b-a),Math.cos(b-a))*180/Math.PI;
    $('#corner-metrics').textContent=(i===0||i===n-1)&&t.complete===false?'Open road endpoint':`${angle<0?'Left':'Right'} turn · ${Math.round(Math.abs(angle))}° control-point deflection`;
  }
  function refresh(){
    const t=api.getTrack(),i=api.getSelected(),p=t.points[i];refreshBoards(t);const key=JSON.stringify(t.points.map(p=>p.cornerName||''));
    const selected=api.getSelectedPoints();$('#corner-selection-note').textContent=selected.length>1?`${selected.length} road points selected. Values shown are from active point ${i+1}; curve, kerb and height changes apply to every selected point. Drag any selected handle to move the group. Escape clears the selection.`:'Shift-click handles to edit curve, kerb and height settings together. Distance boards are configured per detected turn.';
    $('#previous-corner').disabled=$('#next-corner').disabled=!t.points.length;$('#corner-select').disabled=!t.points.length;
    if(key!==lastPoints){lastPoints=key;$('#corner-select').replaceChildren();const placeholder=new Option('Choose a road point','-1');placeholder.disabled=true;$('#corner-select').append(placeholder);t.points.forEach((p,j)=>$('#corner-select').append(new Option(`${String(j+1).padStart(2,'0')} · ${p.cornerName||'Road point'}`,String(j))));}
    $('#corner-select').value=String(p?i:-1);$('#corner-controls').hidden=!p;$('#corner-empty').hidden=!!p;$('#corner-number').textContent=p?`POINT ${i+1}`:'';if(!p)return;
    const c=cornerSettings(p);$('#corner-name').value=c.cornerName;$('#corner-tangent').value=c.tangentRotation;$('#tangent-value').textContent=`${c.tangentRotation>0?'+':''}${c.tangentRotation}°`;
    for(const [id,key,out] of [['rounding','rounding','rounding'],['entry','entryStrength','entry'],['exit','exitStrength','exit']]){$('#corner-'+id).value=Math.round(c[key]*100);$('#'+out+'-value').textContent=`${Math.round(c[key]*100)}%`;}
    $('#corner-kerbs').value=c.kerbs;$('#corner-kerb-width').value=c.kerbWidth;$('#corner-banking').value=p.bank||0;$('#corner-elevation').value=p.elevation||0;$('#paste-corner').disabled=!copied;
    panel.querySelectorAll('[data-rounding]').forEach(b=>b.classList.toggle('active',Math.abs(Number(b.dataset.rounding)-c.rounding)<.01));
    panel.querySelectorAll('[data-corner-preset]').forEach(b=>b.setAttribute('aria-pressed',String(Object.entries(PRESETS[b.dataset.cornerPreset]).every(([key,v])=>Math.abs(c[key]-v)<.01))));
    drawPreview(t,i);$('#corner-hint').textContent=(t.smooth?'Changes appear in the editor, 3D preview, and exported mod. ':'Enable Smooth corners in Design to use curve shaping. ')+(t.export?.kerbs===false?'Enable kerbs in Export to include your kerb settings.':'Kerbs apply to the outgoing section.');
  }
  return {refresh};
}
